insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000030001', '$k=1$.', 'A continuidade exige que o valor atribuído no ponto seja igual ao valor para o qual a expressão se aproxima pelas duas direções. Como polinômios são contínuos, basta avaliar a expressão x ao quadrado no ponto indicado.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000300011', '40000000-0000-4000-8000-000000030001', 'Calcule o limite', '$\lim_{x\to1}x^2=1.$', 1), ('70000000-0000-4000-8000-000000300012', '40000000-0000-4000-8000-000000030001', 'Use a continuidade', '$f(1)=\lim_{x\to1}f(x).$', 2), ('70000000-0000-4000-8000-000000300013', '40000000-0000-4000-8000-000000030001', 'Defina k', '$k=1.$', 3)
