insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000300161', '40000000-0000-4000-8000-000000030016', 'A', '$12$ cm²/s', 1), ('50000000-0000-4000-8000-000000300162', '40000000-0000-4000-8000-000000030016', 'B', '$6$ cm²/s', 2), ('50000000-0000-4000-8000-000000300163', '40000000-0000-4000-8000-000000030016', 'C', '$8$ cm²/s', 3), ('50000000-0000-4000-8000-000000300164', '40000000-0000-4000-8000-000000030016', 'D', '$9$ cm²/s', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000030016', '50000000-0000-4000-8000-000000300161') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000030016', '30000000-0000-4000-8000-000000000027', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000300161', '40000000-0000-4000-8000-000000030016', 'Área e lado mudam com o tempo, então diferencie ambos em relação a t.', 1), ('60000000-0000-4000-8000-000000300162', '40000000-0000-4000-8000-000000030016', 'A regra da cadeia conecta a velocidade do lado à velocidade da área.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000030016', '$dA/dt=12$ cm²/s.', 'Em uma taxa relacionada, primeiro derivamos a relação geométrica em relação ao tempo. Só então inserimos os valores do instante observado. Isso preserva a relação entre a velocidade de crescimento do lado e a velocidade de crescimento da área.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000300161', '40000000-0000-4000-8000-000000030016', 'Derive no tempo', '$\frac{dA}{dt}=2s\frac{ds}{dt}.$', 1), ('70000000-0000-4000-8000-000000300162', '40000000-0000-4000-8000-000000030016', 'Substitua o instante', '$s=2 e \frac{ds}{dt}=3.$', 2), ('70000000-0000-4000-8000-000000300163', '40000000-0000-4000-8000-000000030016', 'Calcule', '$\frac{dA}{dt}=2\cdot2\cdot3=12.$', 3)
