insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000030042', '$F^{\prime}(x)=x^2.$', 'O Teorema Fundamental do Cálculo afirma que derivar uma integral acumulada cujo limite superior é x recupera o integrando avaliado em x. Portanto não é necessário calcular a integral antes de encontrar essa derivada.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
