insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000050010', '50000000-0000-4000-8000-000000500101') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000050010', '30000000-0000-4000-8000-000000000022', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000500101', '40000000-0000-4000-8000-000000050010', 'Derive cada parcela do polinômio separadamente.', 1), ('60000000-0000-4000-8000-000000500102', '40000000-0000-4000-8000-000000050010', 'Depois de derivar, substitua x igual a 1.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000050010', '$f^{\prime}(1)=12$.', 'A derivada mede a taxa de variação instantânea. Em vez de apenas memorizar uma regra, é útil separar a expressão em partes, aplicar a regra apropriada e só então substituir o valor pedido. Essa ordem reduz erros de sinal e deixa claro o significado de cada etapa.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000500101', '40000000-0000-4000-8000-000000050010', 'Derive a potência', '$(x^2)^{\prime}=2x.$', 1), ('70000000-0000-4000-8000-000000500102', '40000000-0000-4000-8000-000000050010', 'Derive o termo linear', '$(10x)^{\prime}=10.$', 2), ('70000000-0000-4000-8000-000000500103', '40000000-0000-4000-8000-000000050010', 'Avalie em 1', '$f^{\prime}(1)=2+10=12.$', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000050011', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000007', 'multiple_choice', 'medium', 'published', 'Calcule a derivada de $g(x)=(x^2+1)^3$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000500111', '40000000-0000-4000-8000-000000050011', 'A', '$6x(x^2+1)^2$', 1), ('50000000-0000-4000-8000-000000500112', '40000000-0000-4000-8000-000000050011', 'B', '$3(x^2+1)^2$', 2), ('50000000-0000-4000-8000-000000500113', '40000000-0000-4000-8000-000000050011', 'C', '$6x(x^2+1)^3$', 3), ('50000000-0000-4000-8000-000000500114', '40000000-0000-4000-8000-000000050011', 'D', '$2x(x^2+1)^2$', 4)
