insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000050018', '$g^{\prime}(x)=6x(x^2+8)^2$.', 'A derivada mede a taxa de variação instantânea. Em vez de apenas memorizar uma regra, é útil separar a expressão em partes, aplicar a regra apropriada e só então substituir o valor pedido. Essa ordem reduz erros de sinal e deixa claro o significado de cada etapa.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000500181', '40000000-0000-4000-8000-000000050018', 'Defina a parte interna', '$u=x^2+8.$', 1), ('70000000-0000-4000-8000-000000500182', '40000000-0000-4000-8000-000000050018', 'Derive a parte externa', '$(u^3)^{\prime}=3u^2.$', 2), ('70000000-0000-4000-8000-000000500183', '40000000-0000-4000-8000-000000050018', 'Multiplique por u linha', '$g^{\prime}(x)=3(x^2+8)^2\cdot 2x=6x(x^2+8)^2.$', 3)
