insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000500211', '40000000-0000-4000-8000-000000050021', 'Uma parábola com coeficiente negativo em x ao quadrado abre para baixo.', 1), ('60000000-0000-4000-8000-000000500212', '40000000-0000-4000-8000-000000050021', 'Encontre o ponto em que a derivada se anula.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000050021', '$x=1$.', 'Uma função quadrática com coeficiente principal negativo tem concavidade voltada para baixo; por isso, seu único ponto crítico é um máximo global. A derivada permite localizar esse ponto sem depender de um esboço do gráfico e confirma onde a taxa de variação muda de positiva para negativa.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000500211', '40000000-0000-4000-8000-000000050021', 'Derive', '$f^{\prime}(x)=-2x+2.$', 1), ('70000000-0000-4000-8000-000000500212', '40000000-0000-4000-8000-000000050021', 'Encontre o crítico', '$-2x+2=0 \Rightarrow x=1.$', 2), ('70000000-0000-4000-8000-000000500213', '40000000-0000-4000-8000-000000050021', 'Classifique', '$f^{primeprime}(x)=-2<0,$ portanto é máximo.', 3)
