insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000050031', '$1$.', 'A regra de L’Hôpital só pode ser usada depois de confirmar uma forma indeterminada adequada. Aqui, seno de zero e zero no denominador produzem zero sobre zero. Derivar os dois lados da fração transforma o limite em uma avaliação direta, pois a nova razão deixa de ser indeterminada.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000500311', '40000000-0000-4000-8000-000000050031', 'Teste a substituição', '$\sin(0)/0=0/0.$', 1), ('70000000-0000-4000-8000-000000500312', '40000000-0000-4000-8000-000000050031', 'Derive numerador e denominador', '$(\sin(1x))^{\prime}=1\cos(1x) e (x)^{\prime}=1.$', 2), ('70000000-0000-4000-8000-000000500313', '40000000-0000-4000-8000-000000050031', 'Avalie o novo limite', '$1\cos(0)=1.$', 3)
