insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060041', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000008', 'multiple_choice', 'hard', 'published', 'Um retângulo tem perímetro 16 m. Qual deve ser a medida de cada lado para que sua área seja máxima?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600411', '40000000-0000-4000-8000-000000060041', 'A', '$4$ m', 1), ('50000000-0000-4000-8000-000000600412', '40000000-0000-4000-8000-000000060041', 'B', '$6$ m', 2), ('50000000-0000-4000-8000-000000600413', '40000000-0000-4000-8000-000000060041', 'C', '$1$ m', 3), ('50000000-0000-4000-8000-000000600414', '40000000-0000-4000-8000-000000060041', 'D', '$8$ m', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060041', '50000000-0000-4000-8000-000000600411') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060041', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600411', '40000000-0000-4000-8000-000000060041', 'Se os lados são x e y, então 2x mais 2y é o perímetro.', 1), ('60000000-0000-4000-8000-000000600412', '40000000-0000-4000-8000-000000060041', 'A área máxima, com perímetro fixo, ocorre quando o retângulo é um quadrado.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060041', '$x=y=4$ m.', 'A otimização começa transformando a restrição geométrica em uma função de uma variável. Com o perímetro fixo, cada aumento em um lado reduz o outro; a área se torna uma parábola côncava. Seu vértice representa a maior área possível e, neste caso, produz lados iguais.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600411', '40000000-0000-4000-8000-000000060041', 'Use o perímetro', '$2x+2y=16 \Rightarrow y=8-x.$', 1), ('70000000-0000-4000-8000-000000600412', '40000000-0000-4000-8000-000000060041', 'Escreva a área', '$A(x)=x(8-x).$', 2), ('70000000-0000-4000-8000-000000600413', '40000000-0000-4000-8000-000000060041', 'Localize o vértice', '$A^{\prime}(x)=8-2x=0 \Rightarrow x=4, y=4.$', 3)
