insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600501', '40000000-0000-4000-8000-000000060050', 'Use o perímetro', '$2x+2y=52 \Rightarrow y=26-x.$', 1), ('70000000-0000-4000-8000-000000600502', '40000000-0000-4000-8000-000000060050', 'Escreva a área', '$A(x)=x(26-x).$', 2), ('70000000-0000-4000-8000-000000600503', '40000000-0000-4000-8000-000000060050', 'Localize o vértice', '$A^{\prime}(x)=26-2x=0 \Rightarrow x=13, y=13.$', 3)
